draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  let opacity = Math.abs(Math.sin(t));
  ctx.globalAlpha = opacity;
  ctx.strokeRect(W/2-100, H/2-25, 200, 50);
  ctx.font = '36px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('BLANK', W/2, H/2);
  ctx.globalAlpha = 1;
  ctx.restore();
}
